describe('Mobile Landscape Orientation', () => {
    beforeEach(() => {
        cy.viewport('iphone-6+'); // Set viewport to iPhone 6 Plus
        cy.visit('/'); // Visit the app's homepage
    });

    it('should display the app correctly in landscape orientation', () => {
        cy.viewport(736, 414); // Set viewport to landscape mode
        cy.get('body').should('have.class', 'landscape'); // Check for landscape class
        cy.get('.header').should('be.visible'); // Check if header is visible
        cy.get('.main-content').should('be.visible'); // Check if main content is visible
        cy.get('.footer').should('be.visible'); // Check if footer is visible
    });

    it('should maintain layout integrity in landscape orientation', () => {
        cy.viewport(736, 414); // Set viewport to landscape mode
        cy.get('.main-content').should('have.css', 'flex-direction', 'row'); // Check layout direction
        cy.get('.sidebar').should('be.visible'); // Ensure sidebar is visible
        cy.get('.sidebar').should('have.css', 'width').and('match', /[0-9]+px/); // Check sidebar width
    });
});
